import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Supernote.html","title":"Supernote","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.48,"words":445},"filePathRelative":"Supernote.md"}`),a={name:`Supernote.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="supernote" tabindex="-1"><a class="header-anchor" href="#supernote"><span>Supernote</span></a></h1><p>Mantaを買った。</p><ul><li><a href="https://supernote.jp/pages/supernote-a5-x2-manta" target="_blank" rel="noopener noreferrer">Supernote Manta – Supernote Japan</a></li><li><a href="https://www.reddit.com/r/Supernote/" target="_blank" rel="noopener noreferrer">reddit r/Supernote</a></li></ul><h2 id="スペック" tabindex="-1"><a class="header-anchor" href="#スペック"><span>スペック</span></a></h2><ul><li>10.7</li><li>300 ppi</li><li>375g</li><li>フロントライト無し</li><li>3600mAh</li><li>Android 11ベース（API レベル30）</li></ul><h2 id="移植した自分アプリ" tabindex="-1"><a class="header-anchor" href="#移植した自分アプリ"><span>移植した自分アプリ</span></a></h2><ul><li><a href="https://github.com/Karino2DIYApp/PngNoteSN" target="_blank" rel="noopener noreferrer">Karino2DIYApp/PngNoteSN: PngNote fork for Supernote</a> これは<a href="./PngNote.html">PngNote</a>のフォーク</li><li><a href="https://github.com/Karino2DIYApp/MagnaSketchSN" target="_blank" rel="noopener noreferrer">Karino2DIYApp/MagnaSketchSN: MagnaSketch fork for Supernote.</a> これは<a href="./マグナスケッチ.html">マグナスケッチ</a>のフォーク</li><li><a href="https://github.com/Karino2DIYApp/KakitoSN" target="_blank" rel="noopener noreferrer">Karino2DIYApp/KakitoSN: 漢字書き取りアプリのSupernoteフォーク</a> 漢字書き取りアプリ<a href="./Kakito.html">Kakito</a>のフォーク</li></ul><p>あと移植した訳では無いが<a href="./Rhinocs.html">Rhinocs</a>はSupernote用の対応を入れた（キーボード周りが少し特殊だったので）</p><h2 id="_2026-10-15-木" tabindex="-1"><a class="header-anchor" href="#_2026-10-15-木"><span>2026-10-15 (木)</span></a></h2><p>とりあえず<a href="./マグナスケッチ.html">マグナスケッチ</a>、<a href="./PngNote.html">PngNote</a>、<a href="./Kakito.html">Kakito</a>がハードウェアレンダリングで動くようになった。 今日から本格的に実用を開始していこうと思う。</p><p>Supernote、かなりいい感じだな。解像度が増えたのもいいし、スタイラスの書き味も凄く良い。 いつまでもペンで何かを書いていたくなるな。</p><h2 id="emrスタイラス-pen-plus-one-を購入-2026-10-13-火" tabindex="-1"><a class="header-anchor" href="#emrスタイラス-pen-plus-one-を購入-2026-10-13-火"><span>EMRスタイラス Pen Plus One を購入 2026-10-13 (火)</span></a></h2><p><a href="./スタイラス.html">スタイラス</a>へ</p><h3 id="ファームウェア関連" tabindex="-1"><a class="header-anchor" href="#ファームウェア関連"><span>ファームウェア関連</span></a></h3><p>redditから公式サイトに行くとupdate.zipがダウンロード出来てそれを手動でインストールすると降ってくるのを待たなくて良い。</p><p><a href="https://support.supernote.com/change-log/how-to-update-your-supernote" target="_blank" rel="noopener noreferrer">ファームウェアのダウンロードとシステムのアップデート - Supernote</a></p><p>展開方法を調べていてroot関連のドキュメントを見つける。</p><p><a href="https://github.com/dwongdev/sugoi-supernote/blob/main/Guides/How%20to%20root%20SN%20A6X2.md" target="_blank" rel="noopener noreferrer">sugoi-supernote/Guides/How to root SN A6X2.md at main · dwongdev/sugoi-supernote</a></p><p>update.zipはFinderからは開けなかったのでterminalからunzipした。</p><p>展開にはmagiskbootを使ってみる。</p><p><a href="https://github.com/PinNaCode/magiskboot_build/releases" target="_blank" rel="noopener noreferrer">Releases · PinNaCode/magiskboot_build</a></p><p>chmod +xして設定から許可して以下を実行。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">./magiskboot unpack boot.img</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="low-latency的な奴" tabindex="-1"><a class="header-anchor" href="#low-latency的な奴"><span>low latency的な奴</span></a></h3><ul><li><a href="https://github.com/mpdairy/monopaint" target="_blank" rel="noopener noreferrer">mpdairy/monopaint</a> コードがAI生成で読みにくい…</li><li><a href="https://github.com/YoramDevGH/AnimInk" target="_blank" rel="noopener noreferrer">YoramDevGH/AnimInk: Offline frame-by-frame animation for the Supernote Nomad e-ink tablet</a><ul><li><a href="https://github.com/YoramDevGH/AnimInk/blob/main/docs/PERFORMANCE_RESEARCH.md" target="_blank" rel="noopener noreferrer">AnimInk/docs/PERFORMANCE_RESEARCH.md at main · YoramDevGH/AnimInk</a></li></ul></li></ul><h3 id="届いた〜-2026-10-09-金" tabindex="-1"><a class="header-anchor" href="#届いた〜-2026-10-09-金"><span>届いた〜！ 2026-10-09 (金)</span></a></h3><p>朝の6時には最寄りの営業所まで来ていたのだが家まで来たのは16時という。まぁ３日で届いたのでなかなか優秀だ。</p><p>開封してセットアップ。開幕WiFiに接続、を押しても無反応でRedditを調べるとskipしてあとで設定すればいいとか。なんか昔GalaxyTabかなんかでもこんなのあったな。</p><p>セットアップして手書き。ペンはBOOX Note3のペンでもいいかな、という感じではある。 自分の机の上だと思ったより暗いなぁ。デスクライトとか無いからなぁ。</p><h3 id="世の中の電子書籍アプリは意外と動く" tabindex="-1"><a class="header-anchor" href="#世の中の電子書籍アプリは意外と動く"><span>世の中の電子書籍アプリは意外と動く</span></a></h3><p>あまり電子書籍を読む気は無かったのだが、Kindleが公式で入れられて結構ちゃんと動いたので、 Aurora Storeから他のも試してみたら、DolyとかSony Readerとかは一通り動く。思ったより動くなぁ。 Dolyは結構買ってるのでDolyが動くなら使ってもいいかもしれん。</p><p>ただネットワークはなんか遅い。出先で何かダウンロードする気は起こらないな。</p><h3 id="アプリをデバッグ実行じてみる" tabindex="-1"><a class="header-anchor" href="#アプリをデバッグ実行じてみる"><span>アプリをデバッグ実行じてみる</span></a></h3><p>サイドロードを有効にするだけで、普通にケーブルつなげてadbが認識する。開発者モードに降りるとかも不要で、そのままデバッグ実行出来る。楽だね。</p><p>RhinocsはonTouchがキーボードからは来ない（画面触るとスタイラスは来る）。通常のEditTextのアプリだと普通に入力は出来るので、何か対応が必要そう。 onPreImeは来てるのでSupernoteだったらこっちで処理するように変更。とりあえずRhinocsは動かせたヽ(´ー｀)ノ</p><p><a href="./マグナスケッチ.html">マグナスケッチ</a>をなんとなくlow renderingっぽい事をしてみたがさっぱり反応せず。コードを見ていると間違いには気づいたが、</p><h3 id="購入-2026-10-06-火" tabindex="-1"><a class="header-anchor" href="#購入-2026-10-06-火"><span>購入 2026-10-06 (火)</span></a></h3><p>本体76980円、ハーフフォリオケースが8980円で合計85960円。 ケースちょっと高い気もしたが、割と満足している人が多いので買ってみる事にした。 スタイラスは買わない。高い割に他の奴でも満足している人は結構多いし、Note3のスタイラスはたぶん使えるのでまずそれを試してから考える。</p><p>2026-10-08 (木) の18時ころに発送メールが届く。 クロネコヤマトの安曇野豊科営業所で発送となっているな。 上海から届くという噂もあったが少なくとも今は長野県あたりから届くっぽいな。</p>`,39)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};